package io.github.diodeme.ji.session.tree;

import io.github.diodeme.ji.ai.ModelRef;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.function.UnaryOperator;

/** Durable repository for one canonical Session document per stable session identity. */
public interface SessionRepository extends AutoCloseable {
    SessionDocument create(String sessionId, ModelRef model, String workingDirectory, Instant createdAt);
    Optional<SessionDocument> load(String sessionId);
    List<SessionDocument.Metadata> list();
    SessionDocument update(String sessionId, long expectedRevision, UnaryOperator<SessionDocument> transition);
    SessionDocument fork(String sourceSessionId, String newSessionId, String lane,
                         Optional<String> targetEntryId, SessionDocument.ForkPosition position,
                         Instant createdAt, long expectedSourceRevision);
    void delete(String sessionId, long expectedRevision);

    @Override
    default void close() {}
}
